library(shiny)
ui &lt;- fluidPage(
  # Global styling and personal font
  tags$head(
    tags$style(HTML("
      body {
        background-color: white;
        color: black;
        font-family: 'Palatino', sans-serif;
      }
      h1, h2, h3 {
        font-family: 'Palatino', serif;
      }
      .shiny-input-container {
        color: #000000;
      }
    "))
  ),

  titlePanel("Assignment 6 – Combined Shiny Apps"),

  tabsetPanel(
    #-------------------
    # Tab 1: mtcars
    #-------------------
    tabPanel("mtcars",
      br(),
      sidebarLayout(
        sidebarPanel(
          h3("mtcars Explorer"),
          selectInput("mtcars_var", "Select variable", choices = names(mtcars))
        ),
        mainPanel(
          plotOutput("mtcars_hist"),
          verbatimTextOutput("mtcars_summary")
        )
      )
    ),

    #-------------------
    # Tab 2: USArrests
    #-------------------
    tabPanel("USArrests",
      br(),
      sidebarLayout(
        sidebarPanel(
          h3("USArrests Viewer"),
          selectInput("usa_state", "Select a state", choices = rownames(USArrests))
        ),
        mainPanel(
          tableOutput("usa_table"),
          plotOutput("usa_bar")
        )
      )
    ),

    #-------------------
    # Tab 3: US Population (uspop)
    #-------------------
    tabPanel("US Population",
      br(),
      h3("US Population Over Time"),
      plotOutput("uspop_plot")
    ),

    #-------------------
    # Tab 4: My Dataset (your own data)
    #-------------------
    tabPanel("My Dataset",
      br(),
      sidebarLayout(
        sidebarPanel(
          h3("Upload Your Own CSV"),
          fileInput("myfile", "Choose CSV file", accept = ".csv"),
          uiOutput("my_var_ui")
        ),
        mainPanel(
          h4("Preview of your data"),
          tableOutput("my_preview"),
          h4("Histogram of selected numeric variable"),
          plotOutput("my_hist")
        )
      )
    )
  )
)

