# SERVER
#========================
server &lt;- function(input, output, session) {

  #----------------------
  # mtcars tab
  #----------------------
  output$mtcars_hist &lt;- renderPlot({
    req(input$mtcars_var)
    hist(mtcars[[input$mtcars_var]],
         main = paste("Histogram of", input$mtcars_var),
         xlab  = input$mtcars_var,
         col   = "skyblue",
         border = "white")
  })

  output$mtcars_summary &lt;- renderPrint({
    req(input$mtcars_var)
    summary(mtcars[[input$mtcars_var]])
  })

  #----------------------
  # USArrests tab
  #----------------------
  output$usa_table &lt;- renderTable({
    req(input$usa_state)
    USArrests[input$usa_state, , drop = FALSE]
  }, rownames = TRUE)

  output$usa_bar &lt;- renderPlot({
    req(input$usa_state)
    vals &lt;- as.numeric(USArrests[input$usa_state, ])
    barplot(vals,
            names.arg = colnames(USArrests),
            main = paste("Arrests in", input$usa_state),
            ylab = "Rate per 100,000",
            col  = "tomato")
  })

  #----------------------
  # US Population (uspop) tab
  #----------------------
  output$uspop_plot &lt;- renderPlot({
    plot(uspop,
         type = "o",
         pch  = 16,
         main = "US Population Over Time",
         xlab = "Year",
         ylab = "Population")
  })

  #----------------------
  # My Dataset tab
  #----------------------
  mydata &lt;- reactive({
    req(input$myfile)
    read.csv(input$myfile$datapath, stringsAsFactors = FALSE)
  })

  output$my_preview &lt;- renderTable({
    req(mydata())
    head(mydata())
  })

  output$my_var_ui &lt;- renderUI({
    req(mydata())
    num_cols &lt;- names(mydata())[sapply(mydata(), is.numeric)]

    if (length(num_cols) == 0) {
      helpText("No numeric columns found in your dataset.")
    } else {
      selectInput("my_var",
                  "Choose numeric variable for histogram",
                  choices = num_cols)
    }
  })

  output$my_hist &lt;- renderPlot({
    req(mydata(), input$my_var)
    hist(mydata()[[input$my_var]],
         main = paste("Histogram of", input$my_var),
         xlab  = input$my_var,
         col   = "steelblue",
         border = "white")
  })
}

#========================
# Run the app in Quarto
#========================
shinyApp(ui, server)


